def test(gin, gout, mk, rule):
    H,W=len(gin),len(gin[0])
    rows={}; cols={}
    for r in range(H):
        for c in range(W):
            if gin[r][c]==mk:
                rows.setdefault(r,[]).append(c); cols.setdefault(c,[]).append(r)
    out=[]
    for r in range(H):
        row=[]
        for c in range(W):
            if gin[r][c]==mk: row.append(mk); continue
            row.append(3 if rule(r,c,rows,cols,H,W) else gin[r][c])
        out.append(row)
    diff=[(r,c,gout[r][c],out[r][c]) for r in range(H) for c in range(W) if gout[r][c]!=out[r][c]]
    return len(diff), diff

def between(r,c,rows,cols,H,W):
    rb=any(a<c<b for a in rows.get(r,[]) for b in rows.get(r,[]) if a<b)
    cb=any(a<r<b for a in cols.get(c,[]) for b in cols.get(c,[]) if a<b)
    return rb or cb

